function isPerfect(n) {
  var sum = 0;
  for (var d = 1; d < n; d++) {
    if (n % d === 0) {
      sum += d;
    }
  }
  return sum === n;
}

[6, 12].forEach(function (n) {
  console.log(n + " " + isPerfect(n));
});
